// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// ==============================================================================
// Código do nó Code "Mensagens" (Modo: Run Once for All Items)
// Desafio DIO: Assistente de Investimentos com RPA e n8n
// ==============================================================================

// 1. Catálogo oficial de investimentos do laboratório (docs/data.csv)
const catalogoInvestimentos = {
  "Conservador": [
    { produto: "Tesouro Selic", rentabilidade: "13.0%", minimo: "R$ 500,00", descricao: "Segurança e liquidez diária com garantia do Tesouro Nacional." },
    { produto: "CDB Liquidez Diária", rentabilidade: "12.5%", minimo: "R$ 1.000,00", descricao: "Proteção do FGC e resgate imediato a qualquer momento." },
    { produto: "Poupança", rentabilidade: "6.2%", minimo: "R$ 100,00", descricao: "Isenção total de IR e simplicidade para reserva imediata." }
  ],
  "Moderado": [
    { produto: "CDB Prefixado", rentabilidade: "14.0%", minimo: "R$ 1.000,00", descricao: "Taxa e retorno garantidos até a data de vencimento." },
    { produto: "Tesouro IPCA+", rentabilidade: "15.0%", minimo: "R$ 1.000,00", descricao: "Rentabilidade real com proteção contra a inflação." },
    { produto: "Fundo Multimercado", rentabilidade: "16.0%", minimo: "R$ 5.000,00", descricao: "Diversificação inteligente entre moedas, juros e renda variável." }
  ],
  "Arrojado": [
    { produto: "Ações (Ibovespa)", rentabilidade: "Variável", minimo: "R$ 500,00", descricao: "Participação nas maiores empresas do país com foco em valorização e dividendos." },
    { produto: "FIIs (Fundos Imobiliários)", rentabilidade: "Variável", minimo: "R$ 100,00", descricao: "Recebimento de renda passiva mensal isenta de IR." },
    { produto: "Criptomoedas (Bitcoin/ETH)", rentabilidade: "Alta Volatilidade", minimo: "R$ 100,00", descricao: "Exposição a ativos digitais globais com alto potencial de valorização." }
  ]
};

// 2. Extração resiliente dos dados de entrada
// Suporta: payload do Webhook (body.clientes), array direto ou itens separados
const items = $input.all();
let listaClientes = [];

for (const item of items) {
  const json = item.json;

  if (json.body && Array.isArray(json.body.clientes)) {
    listaClientes.push(...json.body.clientes);
  } else if (Array.isArray(json.clientes)) {
    listaClientes.push(...json.clientes);
  } else if (json.body && typeof json.body === 'object' && json.body.nome) {
    listaClientes.push(json.body);
  } else if (json.nome) {
    listaClientes.push(json);
  }
}

// Fallback caso cheguem itens avulsos em outro formato
if (listaClientes.length === 0 && items.length > 0) {
  listaClientes = items.map(i => i.json);
}

// 3. Cruzamento de perfil e geração da mensagem para cada cliente
const resultados = listaClientes.map(cliente => {
  const nome = cliente.nome || "Cliente";
  const email = cliente.email || "";
  const saldo = cliente.saldo || "R$ 0,00";
  const perfilOriginal = (cliente.perfil || "Conservador").trim();

  // Padronizar capitalização (ex: "conservador" -> "Conservador")
  const perfil = perfilOriginal.charAt(0).toUpperCase() + perfilOriginal.slice(1).toLowerCase();

  // Buscar opções recomendadas para o perfil
  const opcoes = catalogoInvestimentos[perfil] || catalogoInvestimentos["Conservador"];

  // Montar lista de produtos formatada
  const textoOpcoes = opcoes.map((op, idx) => 
    `${idx + 1}. *${op.produto}* (Aplicação mínima: ${op.minimo})\n   • Rentabilidade estimada: ${op.rentabilidade}\n   • Detalhe: ${op.descricao}`
  ).join("\n\n");

  // Mensagem personalizada completa
  const mensagem = 
`Olá, *${nome}*! 👋

Identificamos que seu perfil de investidor é *${perfil}* e você possui um saldo disponível de *${saldo}*.

Com base na sua estratégia, selecionamos as melhores opções de investimento disponíveis para você:

${textoOpcoes}

💡 *Dica:* Para começar a investir ou simular rendimentos futuros, responda a esta mensagem ou acesse seu aplicativo. Estamos à disposição para ajudar você a alcançar seus objetivos!

Atenciosamente,
*Assessoria de Investimentos*`;

  return {
    json: {
      nome,
      email,
      saldo,
      perfil,
      mensagem,
      produtosSugeridos: opcoes,
      criadoEm: new Date().toISOString()
    }
  };
});

return resultados;
